SINA_SMART["physics1-osmosis"] = {"lecture":"physics1-osmosis","title":"Osmotic phenomena and oncotic pressure","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-osmosis:e0","text":"Osmosis: solvent flows through a semipermeable membrane toward the more concentrated side.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-osmosis:e1","text":"Osmotic pressure: minimum pressure to stop the flow.","topic":"Osmotic pressure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-osmosis:e2","text":"Van't Hoff: ω = RTC (C = osmolarity of non-diffusible particles).","topic":"Osmotic pressure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-osmosis:e3","text":"Macromolecules: ω = RTC + RTvC² (excluded volume).","topic":"Osmotic pressure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-osmosis:e4","text":"Macro-ions: Donnan effect adds pressure and a potential.","topic":"Osmotic pressure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-osmosis:e5","text":"Oncotic pressure ≈ 28 mmHg (3.2 kPa), ~85% from albumin.","topic":"Oncotic pressure","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-osmosis:e6","text":"Oncotic pressure keeps water in capillaries; low albumin → oedema.","topic":"Oncotic pressure","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1e4vkjh":"a","qsm1gp":"a","f6d2bb":"a","oomr2g":"a","1a7xreh":"a","1plnshp":"a","15ymb3t":"a","12d1bgp":"a","1ylmb0d":"a","194z62y":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-osmosis:e0":{"s":0,"u":["Osmosis: solvent flows through a semipermeable membrane toward the more concentrated side.","Osmosis is the flow of solvent (water) through a semipermeable membrane from a less concentrated to a more concentrated solution, driven by the solvent's chemical potential gradient; it tends to equalise concentrations."],"dp":[]},"physics1-osmosis:e1":{"s":1,"u":["Osmotic pressure: minimum pressure to stop the flow.","Osmotic pressure ω is the minimum pressure to apply to the concentrated side to prevent solvent passing from the dilute side.","Na-proteinates) with diffusible Na⁺ and Cl⁻, the Donnan equilibrium leaves unequal diffusible-ion concentrations (Cl⁻ lower and Na⁺ higher on the protein side), a Donnan potential , and an extra Donnan pressure adding to the osmotic pressure."],"dp":[]},"physics1-osmosis:e2":{"s":1,"u":["Van't Hoff: ω = RTC (C = osmolarity of non-diffusible particles).","For dilute solutions of small particles, Van't Hoff's law: ω = R·T·C (Pa), with C = osmolarity of non-diffusible particles , T in kelvin, R = 8.31 J·mol⁻¹·K⁻¹: ω rises linearly with C; measured with a membrane osmometer."],"dp":[{"h":"Why only non-diffusible particles count","t":"A solute that crosses the membrane freely equalises on both sides and creates no lasting water pull. Only particles held back by the membrane, such as proteins at the capillary wall, sustain an osmotic gradient. That is why small solutes like glucose and sodium, which cross capillaries easily, contribute little to the oncotic pressure that holds water in the blood. Source: the lecture's Van't Hoff law and oncotic pressure slides."}]},"physics1-osmosis:e3":{"s":1,"u":["Macromolecules: ω = RTC + RTvC² (excluded volume).","For neutral macromolecules , measured ω is slightly higher: ω = aC + bC² (+ dC³): ω = RTC + RTvC² , the C² term due to the excluded volume v of the large molecules."],"dp":[]},"physics1-osmosis:e4":{"s":1,"u":["Macro-ions: Donnan effect adds pressure and a potential.","Na-proteinates) with diffusible Na⁺ and Cl⁻, the Donnan equilibrium leaves unequal diffusible-ion concentrations (Cl⁻ lower and Na⁺ higher on the protein side), a Donnan potential , and an extra Donnan pressure adding to the osmotic pressure."],"dp":[]},"physics1-osmosis:e5":{"s":2,"u":["Oncotic pressure ≈ 28 mmHg (3.2 kPa), ~85% from albumin.","Plasma oncotic pressure ≈ 28 mmHg (3.2 kPa) at 37 °C , mainly from albumin (~85%) .","The oncotic (Starling) pressure is the osmotic pressure of the macromolecules (proteins) of a biological fluid; it depends on the number, size and shape of the particles."],"dp":[]},"physics1-osmosis:e6":{"s":2,"u":["Oncotic pressure keeps water in capillaries; low albumin → oedema.","Plasma oncotic pressure ≈ 28 mmHg (3.2 kPa) at 37 °C , mainly from albumin (~85%) .","It pulls water into the capillaries, balancing hydrostatic pressure and keeping blood volume constant; a fall (hypoalbuminaemia in liver failure, nephrotic syndrome, malnutrition) favours oedema ."],"dp":[]}},"meta":{"1e4vkjh":{"a":"recall","vg":"physics1-osmosis:e0/recall/1"},"qsm1gp":{"a":"recall","vg":"physics1-osmosis:e1/recall/1"},"f6d2bb":{"a":"recall","vg":"physics1-osmosis:e2/recall/1"},"oomr2g":{"a":"recall","vg":"physics1-osmosis:e2/recall/1"},"1a7xreh":{"a":"recall","vg":"physics1-osmosis:e3/recall/1"},"1plnshp":{"a":"relationship","vg":"physics1-osmosis:e4/relationship/1"},"15ymb3t":{"a":"recall","vg":"physics1-osmosis:e5/recall/1"},"12d1bgp":{"a":"relationship","vg":"physics1-osmosis:e5/relationship/1"},"1ylmb0d":{"a":"relationship","vg":"physics1-osmosis:e6/relationship/1"},"194z62y":{"a":"recall","vg":"physics1-osmosis:e5/recall/2"}},"explRev":"9c6f63691688"};
